import logging
import pprint
from abc import ABCMeta, abstractmethod
from six.moves import queue
from copy import deepcopy
from ute_common_abstract_core.message import NotFoundKey
from ta_measurements.configuration import MeasurementConfiguration
from ta_messaging.message_verifiers import message_verifier


class MeasurementParser(object):
    """
    MeasurementParser abstract class implementation.
    """
    __metaclass__ = ABCMeta

    def __init__(self):
        self.notify_queue = queue.Queue()
        self.measurement = []  # can be index 1,2,3,...,-1

    def notify_event_changed(self):
        '''
        Notifies through queue that event occurred so it can be accessed.
        :param event_num:
        :return:
        '''
        self.notify_queue.put(None)

    @message_verifier
    def process_measurement(self, rrc_reconfiguration_message):
        '''
        Callback function used by message observer to process RRCConnectionReconfiguration and other required messages and notify about
        event new occurrence.
        :param rrc_reconfiguration_message:
        :return:
        '''
        self.process_reconfiguration(rrc_reconfiguration_message)
        self.notify_event_changed()
        return True

    @abstractmethod
    def process_reconfiguration(self, rrc_reconfiguration_message):
        '''
        Function that based on received RRCConnectionReconfiguration massage and previous -1 (stored) measurement state calculates the current
        measurement state and stores it. Also stores each RRCConnectionReconfiguration message.
        :param rrc_reconfiguration_message:
        :return:
        '''
        pass

    def clear_collected_measurements(self):
        """
        Clears measurements list.
        :return:
        """
        self.measurement = []

    @abstractmethod
    def get_raw_measurement(self, event_number):
        '''
        Implementation dependant on storage container used.
        :return:
        '''
        pass

    @property
    @abstractmethod
    def measurements(self):
        '''
        Implementation dependant on storage container used.
        :return:
        '''
        # to do, returns object that can be indexed
        pass

    @property
    @abstractmethod
    def counted_events(self):
        '''
        Implementation dependant on storage container used.
        :return:
        '''
        pass


class MeasurementParserByReconfigurationOnly(MeasurementParser):
    """
    Parser class that will process measurements based only on RRCConnectionReconfiguration
    and will not wait, for example, for UE to confirm measurement installation
    thru RRCConnectionReconfigurationComplete message.
    """
    def __init__(self):
        super(MeasurementParserByReconfigurationOnly, self).__init__()
        # ['measObjectToRemoveList', 'measObjectToAddModList', 'reportConfigToRemoveList',
        #  'reportConfigToAddModList', 'measIdToRemoveList', 'measIdToAddModList',
        #  'measObjectToAddModList-v9e0', 'measIdToRemoveListExt-r12', 'measIdToAddModListExt-r12',
        #  'measObjectToRemoveListExt-r13', 'measObjectToAddModListExt-r13', 'measIdToAddModList-v1310',
        #  'measIdToAddModListExt-v1310']

    @property
    def counted_events(self):
        """
        Returns numbers of measurements processed.
        """
        return len(self.measurement)

    @property
    def measurements(self):
        """
        Returns processed measurements.
        """
        return self.measurement

    def process_reconfiguration(self, rrc_reconfiguration_message):
        """
        Gets fields from parsed RRCConnectionReconfiguration message and updates installed measurements.
        """
        logging.getLogger('ta_measurements').debug('Analysing message:\n{}'
                                                   .format(pprint.pformat(rrc_reconfiguration_message)))
        measObjectToRemoveList = get_meas_object_to_remove_list(rrc_reconfiguration_message)
        measObjectToAddModList = get_meas_object_to_add_mod_list(rrc_reconfiguration_message)
        reportConfigToRemoveList = get_report_config_to_remove_list(rrc_reconfiguration_message)
        reportConfigToAddModList = get_report_config_to_add_mod_list(rrc_reconfiguration_message)
        measIdToRemoveList = get_meas_id_to_remove_list(rrc_reconfiguration_message)
        measIdToAddModList = get_meas_id_to_add_mod_list(rrc_reconfiguration_message)
        measObjectToAddModList_v9e0 = get_meas_object_to_add_mod_list_v9e0(rrc_reconfiguration_message)
        if not (measObjectToRemoveList or measObjectToAddModList or reportConfigToRemoveList or
                reportConfigToAddModList or measIdToRemoveList or measIdToAddModList or
                measObjectToAddModList_v9e0):
            logging.getLogger('ta_measurements').debug('Message does not contain any measurements')

            return

        try:
            old_config = deepcopy(self.measurement[-1])
        except IndexError:
            new_config = MeasurementConfiguration(measObjectToAddModList, reportConfigToAddModList, measIdToAddModList,
                                                  measObjectToAddModList_v9e0)
        else:
            new_config = old_config.update(measObjectToRemoveList, reportConfigToRemoveList, measIdToRemoveList,
                                           measObjectToAddModList, reportConfigToAddModList, measIdToAddModList,
                                           measObjectToAddModList_v9e0)

        self.measurement.append(new_config)

    def get_raw_measurement(self, event_number):
        """
        To be implemented
        """
        pass


class MeasurementParserByReconfigurationOnly5G(MeasurementParserByReconfigurationOnly):
    """
    Parser class that will process measurements based only on RRCConnectionReconfiguration
    and will not wait, for example, for UE to confirm measurement installation
    thru RRCConnectionReconfigurationComplete message.
    """
    def __init__(self):
        super(MeasurementParserByReconfigurationOnly5G, self).__init__()


def get_meas_object_to_remove_list(rrc_reconfiguration_message):
    """
    Returns measObjectToRemoveList field value from RRCConnectionReconfigurationMessage
    or None if field does not exist.
    """
    try:
        measObjectToRemoveList = rrc_reconfiguration_message.get_value_by_unique_key('measObjectToRemoveList')
        logging.getLogger('ta_measurements').debug('Found measObjectToRemoveList:\n{}'.format(measObjectToRemoveList))
        return measObjectToRemoveList

    except NotFoundKey:
        return None


